import { readFileSync } from 'node:fs';
import type { WorldData } from '../../src/types/world';

/** Captured before Milestone 2 from commit 58baaf8, not generated by the test subject. */
export function landscapeFixture(seed = 42): WorldData {
  const saved = JSON.parse(
    readFileSync(`tests/fixtures/landscape/v10-seed-${seed}.json`, 'utf8'),
  ) as Omit<WorldData, 'tiles'> & { tiles: number[] };
  return { ...saved, tiles: Uint8Array.from(saved.tiles) };
}
